import{z as B,x as d,o as l,c as p,q as t,j as o,D as r,d as e,s as i,S as n,b as E}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"DSL 与嵌入","description":"","frontmatter":{"title":"DSL 与嵌入","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dsl-embedding.md","filePath":"cs/dsl-embedding.md","lastUpdated":1791413859000}'),A={name:"cs/dsl-embedding.md"};function m(D,a,c,h,L,u){const s=d("Mermaid");return l(),p("div",null,[a[2]||(a[2]=t('<h1 id="dsl-与嵌入" tabindex="-1">DSL 与嵌入 <a class="header-anchor" href="#dsl-与嵌入" aria-label="Permalink to &quot;DSL 与嵌入&quot;">​</a></h1><div class="epigraph"><p>领域语言可以是独立语法，也可以嵌入宿主：深嵌入建 AST 再编译，浅嵌入用宿主函数与重载当语法。</p><footer>—— 据 Hudak, Building Domain-Specific Embedded Languages；Fowler 对 DSL 的讨论；对照[宏](/cs/macros-hygiene) 与 MLIR 整理</footer></div><p>上一课<a href="/cs/mlir">MLIR</a> 给了编译基础设施。缺口是<strong>语言从哪来</strong>：SQL、正则、构建图。嵌入：Haskell 浅嵌入、Lisp 宏、Rust proc macro。本课钉深/浅，CompCert 下一课把「编译器该对」收束。不写业务 DSL 百科。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>独立 DSL：自己的 lex/yacc，要卫生、错误恢复、JIT 或解释。嵌入：复用宿主类型与工具。浅：组合子，难做跨函数优化。深：数据表示，可 lowering 到 MLIR/LLVM。缺口是<strong>这条选择</strong>，不是方言表。</p><p>宏：可当嵌入的语法糖，卫生课已讲捕获。</p><h3 id="浅嵌入不是「没有编译」" tabindex="-1">浅嵌入不是「没有编译」 <a class="header-anchor" href="#浅嵌入不是「没有编译」" aria-label="Permalink to &quot;浅嵌入不是「没有编译」&quot;">​</a></h3><p>仍有宿主编译。只是没有第二份优化器看见领域结构，除非重载技巧或多阶段（MetaOCaml）。</p><p><span class="marginnote">Hudak 1996。Fowler。Lua 作嵌入语言是另一方向（宿主嵌解释器）。本课编译器视角。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>浅：运算符重载建表达式模板（C++ Eigen 思想）。深：GADT 或 MLIR op。多阶段：生成宿主代码再编译。错误：深嵌入可发领域诊断；浅则是宿主类型错。</p>',11)),(l(),o(n,null,{default:r(()=>[i(s,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20DOM%5B%22%E9%A2%86%E5%9F%9F%E7%A8%8B%E5%BA%8F%22%5D%20--%3E%20SH%5B%22%E6%B5%85%EF%BC%9A%E5%AE%BF%E4%B8%BB%E5%87%BD%E6%95%B0%22%5D%0A%20%20DOM%20--%3E%20DP%5B%22%E6%B7%B1%EF%BC%9AAST%20%2F%20%E6%96%B9%E8%A8%80%22%5D%0A%20%20DP%20--%3E%20LOW%5B%22lowering%20%2F%20MLIR%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,[e("与"),E("a",{href:"/cs/peg-packrat"},"PEG"),e("：独立 DSL 前端常用。与 Wasm：DSL 可目标 Wasm 沙箱。")],-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"阶段混淆：浅嵌入在宿主运行时才算，可能把本该编译期的工作推迟——性能坑。不要用字符串拼接生成代码当卫生 DSL。",-1)),(l(),o(n,null,{default:r(()=>[i(s,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20LR%0A%20%20EX%5B%22%E9%A2%86%E5%9F%9F%E8%A1%A8%E8%BE%BE%E5%BC%8F%20e%20%3D%20a%20%2B%20b%20*%20c%22%5D%20--%3E%20Q1%5B%22%E6%B5%85%E5%B5%8C%E5%85%A5%EF%BC%9A%E5%AE%BF%E4%B8%BB%E5%87%BD%E6%95%B0%E7%AB%8B%E5%8D%B3%E9%80%90%E5%B1%82%E6%B1%82%E5%80%BC%22%5D%0A%20%20Q1%20--%3E%20R1%5B%22%E5%AE%BF%E4%B8%BB%E8%BF%90%E8%A1%8C%E6%97%B6%E6%89%8D%E7%9F%A5%E9%81%93%E6%95%B4%E5%8F%A5%E7%BB%93%E6%9E%84%22%5D%0A%20%20EX%20--%3E%20Q2%5B%22%E6%B7%B1%E5%B5%8C%E5%85%A5%EF%BC%9A%E5%85%88%E5%BB%BA%20AST%20%E5%86%8D%E5%86%B3%E5%AE%9A%E6%80%8E%E4%B9%88%E7%AE%97%22%5D%0A%20%20Q2%20--%3E%20R2%5B%22%E5%8F%AF%E7%9C%8B%E5%85%A8%E5%8F%A5%EF%BC%9A%E8%B7%A8%E5%87%BD%E6%95%B0%E4%BC%98%E5%8C%96%E3%80%81%E9%A2%86%E5%9F%9F%E6%8A%A5%E9%94%99%E3%80%81lowering%22%5D%0A%20%20R2%20--%3E%20GEN%5B%22%E7%94%9F%E6%88%90%2F%E7%BC%96%E8%AF%91%E6%88%90%E5%AE%BF%E4%B8%BB%E6%88%96%20IR%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=t('<p><span class="marginnote">术语翻译：深嵌入就是「你写的领域表达式先变成一个数据结构（AST），再由你写的编译器去分析它」；浅嵌入就是「领域操作直接映射成宿主语言的函数和运算符，宿主立刻执行」。区别在于：领域语义有没有独立的、可被检查的数据表示。</span></p><p><span class="marginnote">直觉类比：浅嵌入像同声传译——一句进来马上翻出去执行，快但看不到全文；深嵌入像先拿到整篇讲稿再统一翻译润色——多一步建稿（AST），但可以做跨段落的改写与优化。</span></p><p><span class="marginnote">数字实例：C++ 的 Eigen 用浅嵌入加运算符重载做表达式模板。天真写法 <code>A = B + C + D</code> 会先算 <code>B + C</code> 分配一个临时矩阵、再加 D 再分配一个；Eigen 把整句先记成表达式对象，确认全貌后一次循环算完、零临时矩阵——这就是浅嵌入「补回深嵌入视角」的典型技巧。</span></p><p>类型：嵌入要不要依值/线性，跟宿主走。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 CompCert。后课默认：DSL 可独立或嵌入；深嵌入才好降到多层 IR。下一课 CompCert 与编译器正确性。</p><p>也不把 DSL 当网络协议 IDL 的全部。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>独立 DSL vs 浅/深嵌入，优化可见性不同。</li><li>深嵌入接到 MLIR/LLVM；浅复用宿主。</li><li>宏是嵌入的语法手段，要卫生。</li><li>出处：Hudak；Fowler；对照 Kohlbecker 宏、Lattner MLIR。</li></ul>',9))])}const S=B(A,[["render",m]]);export{F as __pageData,S as default};
